import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import api from "../api";

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [filters, setFilters] = useState({
    status: "",
    search: ""
  });

  useEffect(() => {
    fetchJobs();
  }, []); // Empty dependency array = run once on mount

  const fetchJobs = async () => {
    setLoading(true);
    setError("");
    
    try {
      // Build query parameters for filtering
      const params = new URLSearchParams();
      if (filters.status) params.append("status", filters.status);
      if (filters.search) params.append("search", filters.search);
      
      const response = await api.get(`/jobs?${params.toString()}`);
      setJobs(response.data);
    } catch (err) {
      setError("Failed to load jobs. Please try again.");
      console.error("Error fetching jobs:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const applyFilters = () => {
    fetchJobs();
  };

  if (loading) return <div className="loading">Loading jobs...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="jobs-container">
      <div className="jobs-header">
        <h2>Audio Processing Jobs</h2>
        <Link to="/jobs/new" className="create-job-btn">
          Create New Job
        </Link>
      </div>
      
      {/* Filters Section */}
      <div className="filters">
        <input
          type="text"
          name="search"
          placeholder="Search jobs..."
          value={filters.search}
          onChange={handleFilterChange}
        />
        
        <select name="status" value={filters.status} onChange={handleFilterChange}>
          <option value="">All Status</option>
          <option value="pending">Pending</option>
          <option value="processing">Processing</option>
          <option value="completed">Completed</option>
          <option value="failed">Failed</option>
        </select>
        
        <button onClick={applyFilters}>Apply Filters</button>
      </div>
      
      {/* Jobs Grid */}
      {jobs.length === 0 ? (
        <div className="no-jobs">No jobs found. Create your first job!</div>
      ) : (
        <div className="jobs-grid">
          {jobs.map(job => (
            <Link to={`/jobs/${job.id}`} key={job.id} className="job-card">
              <div className="job-status-badge" data-status={job.status}>
                {job.status}
              </div>
              
              <h3>{job.title}</h3>
              <p className="job-description">{job.description}</p>
              
              <div className="job-meta">
                <span className="job-reward">
                  Reward: ${job.reward}
                </span>
                <span className="job-deadline">
                  Deadline: {new Date(job.deadline).toLocaleDateString()}
                </span>
              </div>
              
              <div className="job-stats">
                <span>Files: {job.audio_files_count || 0}</span>
                <span>Submissions: {job.submissions_count || 0}</span>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

export default Jobs;
